.baris-tugas {
  display: flex;
  align-items: center; /* Merapikan sumbu vertikal */
  justify-content: space-between; /* Mendorong tombol X ke ujung kanan */
  background-color: #eee;
  padding: 10px;
  margin-bottom: 5px;
}

.isi-tugas {
  display: flex;
  align-items: center;
  gap: 10px;
}

/* Hilangkan titik bulat dari ul */
ul {
  list-style: none;
  padding: 0;
}

